"""

import string

ALPHABET = string.ascii_lowercase
M = len(ALPHABET)


def _check_coprime(a):
    if math_gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")


def _modular_multiplicative_inverse(a):
    """Return the modular multiplicative inverse of `a` mod M.

    Only valid when `a` and M are coprime.
    """
    for x in range(1, M):
        if (a * x) % M == 1:
            return x
    raise ValueError("a and m must be coprime.")


import math


def math_gcd(a, b):
    return math.gcd(a, b)


def encode(plain_text, a, b):
    _check_coprime(a)
    encoded = []
    for char in plain_text.lower():
        if char in ALPHABET:
            i = ALPHABET.index(char)
            encoded.append(ALPHABET[(a * i + b) % M])
        elif char.isdigit():
            encoded.append(char)
    return " ".join("".join(encoded)[i:i + 5] for i in range(0, len(encoded), 5))


def decode(ciphered_text, a, b):
    _check_coprime(a)
    a_inv = _modular_multiplicative_inverse(a)
    decoded = []
    for char in ciphered_text:
        if char in ALPHABET:
            y = ALPHABET.index(char)
            decoded.append(ALPHABET[(a_inv * (y - b)) % M])
        elif char.isdigit():
            decoded.append(char)
    return "".join(decoded)

